('writing_prompt','working-from-home','Working from home','Do the advantages of working from home outweigh the disadvantages?','published',30,'{"task":"task_2","prompt":"Many employees now work from home for part of the week. Do the advantages of this development outweigh the disadvantages? Give reasons for your answer and include relevant examples."}'),
('speaking_plan','learning','Learning something new','A three-part speaking interview about learning and skills.','published',10,'{"turns":[{"part":1,"seconds":40,"prep_seconds":0,"prompt":"Welcome to your speaking practice. We will begin with some questions about everyday life. Do you work or study, and what do you enjoy about it?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"What is a typical weekday like for you?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"What do you like about the area where you live?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"Now let us talk about learning. What is something you enjoyed learning as a child?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"Do you prefer learning alone or with other people? Why?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"How do you usually find time to learn something new?"},{"part":2,"seconds":120,"prep_seconds":60,"prompt":"Now we come to Part 2. Describe a useful skill you learned. Say what the skill is, when and how you learned it, and who helped you. Explain why this skill has been useful. You will have one minute to prepare, then up to two minutes to speak."},{"part":3,"seconds":60,"prep_seconds":0,"prompt":"We have been discussing learning a skill. In Part 3, let us consider learning more broadly. Why do some adults find it difficult to learn new skills?"},{"part":3,"seconds":60,"prep_seconds":0,"prompt":"How has technology changed the way people learn?"},{"part":3,"seconds":60,"prep_seconds":0,"prompt":"Should schools give more time to practical skills or academic knowledge? Why?"},{"part":3,"seconds":60,"prep_seconds":0,"prompt":"Who should be responsible for helping workers learn new skills: employers, governments, or individuals?"}]}'),
('speaking_plan','places','A place worth visiting','A three-part speaking interview about places and tourism.','published',20,'{"turns":[{"part":1,"seconds":40,"prep_seconds":0,"prompt":"Welcome to your speaking practice. We will begin with some questions about everyday life. Do you work or study, and what do you enjoy about it?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"What is a typical weekday like for you?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"What do you like about the area where you live?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"Now let us talk about places. Where do you like to spend your free time?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"Do you prefer visiting familiar places or discovering new ones? Why?"},{"part":1,"seconds":40,"prep_seconds":0,"prompt":"Has the place where you live changed since you were younger?"},{"part":2,"seconds":120,"prep_seconds":60,"prompt":"Now we come to Part 2. Describe a place you visited that you would recommend to a friend. Say where it is, when you visited, and what you did there. Explain why your friend would enjoy it. You will have one minute to prepare, then up to two minutes to speak."},{"part":3,"seconds":60,"prep_seconds":0,"prompt":"We have been discussing a place you visited. In Part 3, let us consider tourism more broadly. What makes a place attractive to visitors?"},{"part":3,"seconds":60,"prep_seconds":0,"prompt":"How can tourism benefit the people who live in a place?"},{"part":3,"seconds":60,"prep_seconds":0,"prompt":"What problems can large numbers of visitors cause, and how could these be reduced?"},{"part":3,"seconds":60,"prep_seconds":0,"prompt":"Do you think virtual experiences will ever replace travelling to a place in person? Why or why not?"}]}');
