CREATE TABLE managed_content (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    kind text NOT NULL CHECK (kind IN ('daily_challenge','achievement','vocabulary','writing_prompt','speaking_plan')),
    slug text NOT NULL,
    title text NOT NULL,
    summary text NOT NULL DEFAULT '',
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')),
    sort_order integer NOT NULL DEFAULT 0,
    starts_at timestamptz,
    ends_at timestamptz,
    data jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_by uuid REFERENCES admins(id) ON DELETE SET NULL,
    updated_by uuid REFERENCES admins(id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE(kind, slug),
    CHECK (starts_at IS NULL OR ends_at IS NULL OR starts_at < ends_at)
);
CREATE INDEX managed_content_delivery_idx ON managed_content(kind,status,sort_order,created_at);

